BEGIN TRANSACTION;
CREATE TABLE google_posts (
        post_id TEXT PRIMARY KEY,
        title TEXT NOT NULL,
        content TEXT,
        call_to_action TEXT,
        scheduled_time TEXT,
        status TEXT DEFAULT 'Published',
        created_at TEXT
    );
CREATE TABLE google_reviews (
        review_id TEXT PRIMARY KEY,
        author_name TEXT NOT NULL,
        rating INTEGER NOT NULL,
        comment TEXT,
        sentiment TEXT,
        review_date TEXT,
        status TEXT DEFAULT 'Published',
        reply_text TEXT,
        created_at TEXT
    );
CREATE TABLE leads_crm (
        phone TEXT PRIMARY KEY,
        name TEXT,
        status TEXT,
        requirement TEXT,
        budget TEXT,
        location TEXT,
        language TEXT,
        last_intent TEXT,
        last_message TEXT,
        last_updated TEXT,
        created_at TEXT
    );
CREATE TABLE mmr_projects (
            project_id TEXT PRIMARY KEY,
            name TEXT NOT NULL,
            developer TEXT,
            region TEXT NOT NULL,
            sub_area TEXT NOT NULL,
            locality TEXT,
            configurations TEXT,
            starting_price TEXT,
            price_range TEXT,
            rate_sq_ft TEXT,
            carpet_area TEXT,
            rera_number TEXT,
            status TEXT,
            possession TEXT,
            amenities TEXT,
            highlights TEXT
        );
CREATE TABLE rent_agreements (
        agreement_id TEXT PRIMARY KEY,
        client_name TEXT NOT NULL,
        phone TEXT NOT NULL,
        role TEXT DEFAULT 'Owner / Tenant',
        property_address TEXT,
        monthly_rent TEXT,
        deposit_amount TEXT,
        agreement_period TEXT DEFAULT '11 Months',
        cost_per_side REAL DEFAULT 1750.0,
        total_cost REAL DEFAULT 3500.0,
        biometric_status TEXT DEFAULT 'Scheduled / Doorstep',
        biometric_slot TEXT,
        official_qr_pdf TEXT,
        status TEXT DEFAULT 'Drafting / In Progress',
        notes TEXT,
        created_at TEXT,
        updated_at TEXT
    );
COMMIT;
